import numpy as np
try:
    from scipy.optimize import linprog
    SCIPY_AVAILABLE = True
except Exception:
    SCIPY_AVAILABLE = False

# ---------------- Utilities ----------------

def _micro_shrink(r, eps=1e-12):
    r = np.asarray(r, dtype=float).copy()
    r *= (1.0 - eps)
    return r

def _pairwise_distances(C):
    D2 = np.sum((C[:,None,:]-C[None,:,:])**2, axis=-1)
    np.fill_diagonal(D2, 0.0)
    return np.sqrt(D2, out=np.zeros_like(D2), where=(D2>0))

def _boundary_margins(C):
    x, y = C[:,0], C[:,1]
    return np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))

def _solve_lp_for_radii(C):
    n = C.shape[0]
    if not SCIPY_AVAILABLE:
        b = _boundary_margins(C)
        r = np.minimum(b, 1e-3)
        return r, float(np.sum(r)), True
    b = _boundary_margins(C)
    D = _pairwise_distances(C)
    rows, rhs = [], []
    for i in range(n):
        for j in range(i+1, n):
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            rows.append(row); rhs.append(D[i,j])
    A_ub = np.vstack(rows) if rows else None
    b_ub = np.array(rhs, dtype=float) if rhs else None
    c = -np.ones(n)
    bounds = [(0.0, float(max(0.0, bi))) for bi in b]
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        return np.zeros(n), 0.0, False
    r = res.x.astype(float)
    return r, float(-res.fun), True

def _min_slacks(C, r):
    x, y = C[:,0], C[:,1]
    b_sl = np.minimum(np.minimum(x - r, 1.0 - x - r), np.minimum(y - r, 1.0 - y - r))
    D = _pairwise_distances(C)
    Rsum = r[:,None] + r[None,:]
    mask = np.triu(np.ones((len(r), len(r)), dtype=bool), 1)
    p_sl = D[mask] - Rsum[mask]
    return float(np.min(b_sl)), float(np.min(p_sl))

def _clip_box(C, m=1e-6):
    return np.clip(C, m, 1.0 - m)

def _load_artifact():
    try:
        data = np.load("storage/verity/sumr32_best.npz")
        return data["centers"].astype(float), data["radii"].astype(float), True
    except Exception:
        return None, None, False

def _fallback_6x6_minus_corners():
    r = 1.0/12.0; step = 2.0*r
    xs = [r + i*step for i in range(6)]
    ys = [r + j*step for j in range(6)]
    C = []
    for j in range(6):
        for i in range(6):
            if (i in (0,5)) and (j in (0,5)):
                continue
            C.append([xs[i], ys[j]])
    C = np.array(C, dtype=float)
    R = np.full(C.shape[0], r, dtype=float)
    return C, _micro_shrink(R, 1e-12)

# ---------------- Triad motif ablation ----------------

def _tightest_pair(C, r):
    D = _pairwise_distances(C)
    slack = D - (r[:,None] + r[None,:])
    np.fill_diagonal(slack, np.inf)
    n = len(r); best = (None, None, np.inf)
    for i in range(n):
        for j in range(i+1, n):
            s = slack[i,j]
            if s < best[2]:
                best = (i, j, s)
    return best

def _nearest_third(i, j, C):
    m = 0.5*(C[i] + C[j])
    diff = C - m
    d2 = np.sum(diff*diff, axis=1)
    d2[i] = np.inf; d2[j] = np.inf
    return int(np.argmin(d2))

def _attempt_triad_ablation(C0, r0, O0):
    i, j, _ = _tightest_pair(C0, r0)
    if i is None or j is None:
        return None
    k = _nearest_third(i, j, C0)
    v = C0[j] - C0[i]
    nrm = np.linalg.norm(v)
    if nrm < 1e-15:
        return None
    u = v / nrm
    steps = (5e-4, 3e-4, 2e-4, 1e-4)
    betas = (1.0, 0.5)  # ablation vs prior {0.5, 0.3}
    for s in steps:
        for t in (+1, -1):
            n_perp = np.array([-u[1], u[0]], dtype=float) * float(t)
            m = 0.5*(C0[i] + C0[j])
            dir_k = C0[k] - m
            nk = np.linalg.norm(dir_k)
            dir_k = dir_k / nk if nk > 0 else np.zeros(2)
            for beta in betas:
                C = C0.copy()
                C[i] = C[i] - s*n_perp
                C[j] = C[j] + s*n_perp
                C[k] = C[k] + beta*s*dir_k
                C = _clip_box(C, 1e-6)
                r, O, ok = _solve_lp_for_radii(C)
                if not ok:
                    continue
                r_sh = _micro_shrink(r, 1e-12)
                bmin, pmin = _min_slacks(C, r_sh)
                if (O > O0 + 1e-8) and (bmin >= 1e-10) and (pmin >= 1e-10):
                    return C, r_sh
    return None

def construct_packing():
    n = 32
    C_art, r_art, ok = _load_artifact()
    if not ok or C_art.shape != (n,2) or r_art.shape != (n,):
        return _fallback_6x6_minus_corners()

    if not SCIPY_AVAILABLE:
        return C_art, _micro_shrink(r_art, 1e-12)

    r0, O0, ok2 = _solve_lp_for_radii(C_art)
    if not ok2:
        return C_art, _micro_shrink(r_art, 1e-12)

    res = _attempt_triad_ablation(C_art, r0, O0)
    if res is not None:
        C, r_sh = res
        return C, r_sh

    # No safe improvement: loader-style return
    return C_art, _micro_shrink(r_art, 1e-12)
